const msgpack="undefined"!=typeof window&&window.MessagePack?window.MessagePack:"undefined"!=typeof require?require("@msgpack/msgpack"):null;async function loadN2DFromZip(e){if("undefined"==typeof JSZip)throw new Error("JSZip library not loaded");const o=await JSZip.loadAsync(e.buffer||e);if(o.file("project.msgpack")){console.log("[N2F] Loading MessagePack format (binary)");const e=await o.file("project.msgpack").async("uint8array");if(!msgpack||!msgpack.decode)throw console.error("[N2F] MessagePack library not available, cannot load .msgpack format"),new Error("MessagePack library required but not loaded");try{const o=msgpack.decode(e);return console.log("[N2F] MessagePack decoded successfully"),o}catch(e){throw console.error("[N2F] MessagePack decode failed:",e),new Error("MessagePack decode failed: "+e.message)}}if(o.file("project.json")){console.log("[N2F] Loading JSON format (legacy)");const e=await o.file("project.json").async("string");try{return JSON.parse(e)}catch(e){throw console.error("[N2F] JSON parse failed:",e),new Error("JSON parse failed: "+e.message)}}throw new Error("N2D file contains neither project.msgpack nor project.json")}function isMsgpackAvailable(){return msgpack&&"function"==typeof msgpack.decode}"undefined"!=typeof module&&module.exports&&(module.exports={loadN2DFromZip:loadN2DFromZip,isMsgpackAvailable:isMsgpackAvailable});